// ResultOrg returns the org for any result type.
func (r *Result) ResultOrg() string {
	switch r.Type {
	case TypeCheckpoint:
		if r.Checkpoint != nil {
			return r.Checkpoint.Org
		}
	case TypeCommit:
		if r.Commit != nil {
			return r.Commit.Org
		}
	case TypeSession:
		if r.Session != nil {
			return r.Session.Org
		}
	}
	return ""
}

